using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using RaceDay.Api.Data;
using RaceDay.Api.Models;
namespace RaceDay.Api.Controllers;
[Route("api/results")]
public class ResultsController(RaceDayDbContext db) : ApiControllerBase
{
    public record ResultRequest(int EnrolmentId, string? FinishTime, int? FinishingPosition);
    [HttpGet("mine")] public async Task<IActionResult> Mine() { if(RequireRole("Participant") is IActionResult denied)return denied; return Ok(await db.Results.AsNoTracking().Where(r=>r.Enrolment!.ParticipantId==CurrentUserId).Include(r=>r.Enrolment).ThenInclude(e=>e!.Event).Include(r=>r.Enrolment).ThenInclude(e=>e!.Category).Select(r=>new{r.ResultId,EventName=r.Enrolment!.Event!.Name,EventDate=r.Enrolment.Event.EventDate,CategoryName=r.Enrolment.Category!.Name,r.FinishTime,r.FinishingPosition,r.RecordedAt}).ToListAsync()); }
    [HttpPost] public async Task<IActionResult> Create(ResultRequest request) { if(RequireRole("Organiser") is IActionResult denied)return denied;var en=await db.Enrolments.Include(x=>x.Event).FirstOrDefaultAsync(x=>x.EnrolmentId==request.EnrolmentId);if(en is null)return NotFound(new{message="Enrolment not found."});if(en.Event!.OrganiserId!=CurrentUserId)return Forbid();if(request.FinishingPosition is <=0)return BadRequest(new{message="Finishing position must be a positive number."});TimeSpan? time=null;if(!string.IsNullOrWhiteSpace(request.FinishTime)){if(!TimeSpan.TryParse(request.FinishTime,out var parsed)||parsed<TimeSpan.Zero)return BadRequest(new{message="FinishTime must be a valid time such as 01:25:30."});time=parsed;}var existing=await db.Results.SingleOrDefaultAsync(x=>x.EnrolmentId==request.EnrolmentId);if(existing is not null){existing.FinishTime=time;existing.FinishingPosition=request.FinishingPosition;existing.RecordedAt=DateTime.UtcNow;existing.RecordedByOrganiserId=CurrentUserId!.Value;await db.SaveChangesAsync();return Ok(existing);}var result=new Result{EnrolmentId=request.EnrolmentId,FinishTime=time,FinishingPosition=request.FinishingPosition,RecordedByOrganiserId=CurrentUserId!.Value};db.Results.Add(result);await db.SaveChangesAsync();return CreatedAtAction(nameof(Mine),new{id=result.ResultId},result); }
    [HttpPut("{id:int}")] public async Task<IActionResult> Update(int id,ResultRequest request) { if(RequireRole("Organiser") is IActionResult denied)return denied;var r=await db.Results.Include(x=>x.Enrolment).ThenInclude(e=>e!.Event).FirstOrDefaultAsync(x=>x.ResultId==id);if(r is null)return NotFound();if(r.Enrolment!.Event!.OrganiserId!=CurrentUserId)return Forbid();if(request.FinishingPosition is <=0)return BadRequest(new{message="Finishing position must be positive."});TimeSpan? time=null;if(!string.IsNullOrWhiteSpace(request.FinishTime)){if(!TimeSpan.TryParse(request.FinishTime,out var parsed)||parsed<TimeSpan.Zero)return BadRequest(new{message="FinishTime is invalid."});time=parsed;}r.FinishTime=time;r.FinishingPosition=request.FinishingPosition;r.RecordedAt=DateTime.UtcNow;await db.SaveChangesAsync();return Ok(r); }
}
